+      if (pure) {
+        g94();
+        block(["G1", aw, word]);              // F in degrees per minute
+      } else {
+        block([g93 ? "" : "G93", "G1", xw, yw, zw, aw, word]);
+        g93 = true;
+      }
+    }
+    bPrev = b1; xw0 = xw; yw0 = yw; zw0 = zw;
+  }
+  aSection = a1;
+  aNow = ax.sign * a1;
+  return true;
+}
